<?php $ready=!empty($schema['ready']); ?>
<?php if(!empty($migrationRecoveryKey)): ?><div class="alert alert-warning"><strong>Clave de recuperación creada durante la actualización.</strong><p class="mb-2">Guárdala fuera del servidor. El punto PRE_UPDATE que acabamos de crear está cifrado con esta clave.</p><code class="d-block bg-dark text-white rounded p-3 text-break user-select-all"><?=e($migrationRecoveryKey)?></code></div><?php endif; ?>
<?php if(!empty($migrationPreBackup)): ?><div class="alert alert-info"><strong>Punto PRE_UPDATE creado:</strong> <?=e((string)($migrationPreBackup['filename']??''))?> · SHA-256 <?=e(substr((string)($migrationPreBackup['sha256']??''),0,20))?>…</div><?php endif; ?>

<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Reparación y migraciones</h1><p class="text-muted mb-0">Verifica que la base instalada corresponda con esta versión.</p></div><span class="badge bg-<?=$ready?'success':'warning'?>"><?=$ready?'Base actualizada':'Acción requerida'?></span></div>
<div class="card mb-3"><div class="card-header"><strong>Estado del esquema</strong></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-striped mb-0"><thead><tr><th>Migración</th><th>Estado</th><th>Ejecutada</th></tr></thead><tbody><?php foreach((array)$schema['items'] as $item): ?><tr><td><code><?=e($item['migration'])?></code></td><td><span class="badge bg-<?=($item['state']==='applied'?'success':($item['state']==='checksum_mismatch'?'danger':'warning'))?>"><?=e($item['state'])?></span></td><td><?=e($item['executed_at']??'—')?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php if(!$ready): ?><div class="alert alert-warning"><strong>La aplicación detectó migraciones pendientes.</strong> Ejecútelas antes de abrir el dashboard central.</div><form method="post" action="<?=url('system-run-migrations')?>"><?=csrf_field()?><button class="btn btn-primary"><i class="bi bi-database-up"></i> Ejecutar migraciones pendientes</button></form><?php else: ?><div class="alert alert-success">La estructura está actualizada.</div><a class="btn btn-primary" href="<?=url(AuthManager::landingRoute())?>">Abrir Property Hub</a><?php endif; ?>
